import { AdminPage } from "@/components/admin-page";

export default function Page() {
  return <AdminPage />;
}

"use client";

import { Bar, BarChart, CartesianGrid, XAxis, YAxis } from "recharts";
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/chart";
import { formatValue } from "@/components/chart-formatters";
import {
  type AdminMetric,
  SIGNUP_SERIES,
  type SignupPoint,
} from "@/components/mock-admin";
import { SeriesLegend, seriesColor } from "@/components/series-legend";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { StatDelta, StatValue } from "@/components/ui/stat";

interface AdminOverviewProps {
  hidden: ReadonlySet<string>;
  metrics: readonly AdminMetric[];
  onToggle: (key: string) => void;
  reducedMotion: boolean;
  signups: readonly SignupPoint[];
}

export function AdminOverview({
  hidden,
  metrics,
  onToggle,
  reducedMotion,
  signups,
}: AdminOverviewProps) {
  const shown = SIGNUP_SERIES.filter((item) => !hidden.has(item.key));

  const config = Object.fromEntries(
    SIGNUP_SERIES.map((item, index) => [
      item.key,
      { color: seriesColor(item, index), label: item.label },
    ])
  );

  return (
    <div className="flex flex-col gap-6">
      <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 [&>*]:min-w-0">
        {metrics.map((metric) => (
          <Card key={metric.label} size="sm" variant="outline">
            <CardContent className="flex flex-col gap-1">
              <div className="font-medium text-muted-foreground text-xs">
                {metric.label}
              </div>
              <StatValue>
                {metric.value}
                {metric.delta === null ? null : (
                  <StatDelta direction={metric.direction} value={metric.delta}>
                    {metric.deltaLabel}
                  </StatDelta>
                )}
              </StatValue>
              <div className="text-muted-foreground text-xs">
                {metric.sublabel}
              </div>
            </CardContent>
          </Card>
        ))}
      </section>

      <Card variant="outline">
        <CardHeader>
          {/* Semibold rather than CardTitle's default medium. A dashboard panel
              heading competes with a lot of dense content, so it needs more
              weight than a login card's title does -- but the component stays at
              font-medium, in line with every other *Title part in the library. */}
          <CardTitle className="font-semibold">Signups</CardTitle>
          <CardDescription>
            Trial and paid accounts started each month.
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-3">
          <ChartContainer className="h-[240px] w-full" config={config}>
            <BarChart accessibilityLayer data={[...signups]}>
              <CartesianGrid vertical={false} />
              <XAxis
                axisLine={false}
                dataKey="month"
                tickLine={false}
                tickMargin={8}
              />
              <YAxis
                axisLine={false}
                tickFormatter={(value) => formatValue(value, "number")}
                tickLine={false}
                width="auto"
              />
              <ChartTooltip
                content={
                  <ChartTooltipContent
                    formatter={(value, name) => (
                      <div className="flex flex-1 items-center justify-between gap-3">
                        <span className="text-muted-foreground">
                          {config[name as string]?.label ?? name}
                        </span>
                        <span className="font-medium font-mono tabular-nums">
                          {formatValue(value, "number")}
                        </span>
                      </div>
                    )}
                  />
                }
                cursor={false}
              />
              {shown.map((item, index) => (
                <Bar
                  dataKey={item.key}
                  fill={`var(--color-${item.key})`}
                  isAnimationActive={!reducedMotion}
                  key={item.key}
                  // Cap measured against the VISIBLE bands, so hiding the top
                  // series does not leave the stack uncapped.
                  radius={
                    index === shown.length - 1
                      ? ([4, 4, 0, 0] as [number, number, number, number])
                      : 0
                  }
                  stackId="signups"
                  // Matches the panel's real background: `variant="outline"`
                  // has no fill, so a --card seam would be visibly wrong.
                  stroke="var(--background)"
                  strokeWidth={2}
                />
              ))}
            </BarChart>
          </ChartContainer>
          <SeriesLegend
            hidden={hidden}
            onToggle={onToggle}
            series={SIGNUP_SERIES}
          />
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { AdminOverview } from "@/components/admin-overview";
import { type AdminSection, AdminSidebar } from "@/components/admin-sidebar";
import { AdminTopbar } from "@/components/admin-topbar";
import {
  AdminUsersTable,
  type SortDirection,
  type UserSortKey,
} from "@/components/admin-users-table";
import { adminMetrics, signupsByMonth, users } from "@/components/mock-admin";
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { useReducedMotion } from "@/components/use-reduced-motion";

/** All state lives here; the panels below are presentational. */
export function AdminPage() {
  const reducedMotion = useReducedMotion();

  const [section, setSection] = useState<AdminSection>("overview");
  const [search, setSearch] = useState("");
  const [hidden, setHidden] = useState<ReadonlySet<string>>(new Set());
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const [sort, setSort] = useState<{
    direction: SortDirection;
    key: UserSortKey;
  } | null>({ direction: "asc", key: "name" });
  const [pageIndex, setPageIndex] = useState(0);
  const [pageSize, setPageSize] = useState(5);

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) {
      return users;
    }
    return users.filter(
      (user) =>
        user.name.toLowerCase().includes(query) ||
        user.email.toLowerCase().includes(query)
    );
  }, [search]);

  const sorted = useMemo(() => {
    if (!sort) {
      return filtered;
    }
    const factor = sort.direction === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      const left = a[sort.key];
      const right = b[sort.key];
      if (typeof left === "string" && typeof right === "string") {
        return left.localeCompare(right) * factor;
      }
      return ((left as number) - (right as number)) * factor;
    });
  }, [filtered, sort]);

  const pageCount = Math.max(1, Math.ceil(sorted.length / pageSize));
  const pageRows = sorted.slice(
    pageIndex * pageSize,
    pageIndex * pageSize + pageSize
  );

  const toggleSeries = (key: string) => {
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  const toggleRow = (id: string) => {
    setSelected((current) => {
      const next = new Set(current);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const toggleAllOnPage = (checked: boolean) => {
    setSelected((current) => {
      const next = new Set(current);
      for (const row of pageRows) {
        if (checked) {
          next.add(row.id);
        } else {
          next.delete(row.id);
        }
      }
      return next;
    });
  };

  const cycleSort = (key: UserSortKey) => {
    setPageIndex(0);
    setSort((current) => {
      if (current?.key !== key) {
        return { direction: "asc", key };
      }
      if (current.direction === "asc") {
        return { direction: "desc", key };
      }
      return null;
    });
  };

  return (
    <SidebarProvider>
      <AdminSidebar onSectionChange={setSection} section={section} />
      {/* min-w-0 is required, not cosmetic. Without it a wide table pushes the
          inset open and the whole document gains a horizontal scrollbar — in
          the app this pattern came from, its absence cost +256px of overflow
          across eight pages. Keystone can bake this into components it owns;
          this one is shadcn's, so it lands at the call site. */}
      <SidebarInset className="min-w-0">
        <AdminTopbar
          onSearchChange={(value) => {
            setSearch(value);
            setPageIndex(0);
          }}
          search={search}
          section={section}
        />

        <div className="flex min-w-0 flex-1 flex-col gap-6 p-4 md:p-6">
          {section === "users" ? (
            <AdminUsersTable
              onClearSelection={() => setSelected(new Set())}
              onPageIndexChange={setPageIndex}
              onPageSizeChange={(size) => {
                setPageSize(size);
                // Page 3 of a 5-per-page list does not exist at 50 per page.
                setPageIndex(0);
              }}
              onSort={cycleSort}
              onToggleAll={toggleAllOnPage}
              onToggleRow={toggleRow}
              pageCount={pageCount}
              pageIndex={pageIndex}
              pageSize={pageSize}
              rows={pageRows}
              selected={selected}
              sort={sort}
              totalCount={sorted.length}
            />
          ) : null}

          {section === "overview" ? (
            <AdminOverview
              hidden={hidden}
              metrics={adminMetrics}
              onToggle={toggleSeries}
              reducedMotion={reducedMotion}
              signups={signupsByMonth}
            />
          ) : null}

          {section === "billing" || section === "settings" ? (
            <div className="flex h-[420px] items-center justify-center rounded-xl border border-border border-dashed bg-muted/20 text-muted-foreground text-sm">
              {section === "billing" ? "Billing" : "Settings"} lives here.
            </div>
          ) : null}
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";

import {
  BuildingIcon,
  CreditCardIcon,
  GaugeIcon,
  KeyRoundIcon,
  ReceiptIcon,
  SettingsIcon,
  ShieldCheckIcon,
  UsersIcon,
} from "lucide-react";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarRail,
} from "@/components/ui/sidebar";

/**
 * The sidebar is **shadcn's**, not keystone's — keystone deliberately ships no
 * app shell. It is imported from `@/components/ui/sidebar` in both this demo
 * and the installable copy, which makes it the one import in the block that
 * needs no rewrite between them. See the Interop guide.
 */

export type AdminSection = "billing" | "overview" | "settings" | "users";

interface NavItem {
  badge?: string;
  icon: typeof GaugeIcon;
  key: AdminSection;
  label: string;
}

const NAV: readonly { items: readonly NavItem[]; label: string }[] = [
  {
    items: [
      { icon: GaugeIcon, key: "overview" as const, label: "Overview" },
      { badge: "10", icon: UsersIcon, key: "users" as const, label: "Users" },
    ],
    label: "Workspace",
  },
  {
    items: [
      { icon: CreditCardIcon, key: "billing" as const, label: "Billing" },
      { icon: SettingsIcon, key: "settings" as const, label: "Settings" },
    ],
    label: "Account",
  },
];

const SECONDARY = [
  { icon: ShieldCheckIcon, label: "Audit log" },
  { icon: KeyRoundIcon, label: "API keys" },
  { icon: ReceiptIcon, label: "Invoices" },
];

interface AdminSidebarProps {
  onSectionChange: (section: AdminSection) => void;
  section: AdminSection;
}

export function AdminSidebar({ onSectionChange, section }: AdminSidebarProps) {
  return (
    <Sidebar collapsible="icon">
      <SidebarHeader>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg">
              <div className="flex aspect-square size-8 items-center justify-center rounded-md bg-primary text-primary-foreground">
                <BuildingIcon className="size-4" />
              </div>
              <div className="grid flex-1 text-left leading-tight">
                <span className="truncate font-semibold">Northwind</span>
                <span className="truncate text-muted-foreground text-xs">
                  Team plan
                </span>
              </div>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarHeader>

      <SidebarContent>
        {NAV.map((group) => (
          <SidebarGroup key={group.label}>
            <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                {group.items.map((item) => (
                  <SidebarMenuItem key={item.key}>
                    <SidebarMenuButton
                      isActive={section === item.key}
                      onClick={() => onSectionChange(item.key)}
                      tooltip={item.label}
                    >
                      <item.icon />
                      <span>{item.label}</span>
                    </SidebarMenuButton>
                    {item.badge ? (
                      <SidebarMenuBadge>{item.badge}</SidebarMenuBadge>
                    ) : null}
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}

        <SidebarGroup>
          <SidebarGroupLabel>Security</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {SECONDARY.map((item) => (
                <SidebarMenuItem key={item.label}>
                  <SidebarMenuButton tooltip={item.label}>
                    <item.icon />
                    <span>{item.label}</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg">
              <Avatar className="size-8 rounded-md">
                <AvatarFallback className="rounded-md">AO</AvatarFallback>
              </Avatar>
              <div className="grid flex-1 text-left leading-tight">
                <span className="truncate font-medium">Ada Okonkwo</span>
                <span className="truncate text-muted-foreground text-xs">
                  ada@northwind.io
                </span>
              </div>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarFooter>

      <SidebarRail />
    </Sidebar>
  );
}

"use client";

import { BellIcon, SearchIcon } from "lucide-react";
import type { AdminSection } from "@/components/admin-sidebar";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { Button } from "@/components/ui/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";
import { Separator } from "@/components/ui/separator";
import { SidebarTrigger } from "@/components/ui/sidebar";

const TITLES: Record<AdminSection, string> = {
  billing: "Billing",
  overview: "Overview",
  settings: "Settings",
  users: "Users",
};

interface AdminTopbarProps {
  onSearchChange: (value: string) => void;
  search: string;
  section: AdminSection;
}

export function AdminTopbar({
  onSearchChange,
  search,
  section,
}: AdminTopbarProps) {
  return (
    <header className="flex h-14 shrink-0 items-center gap-2 border-b px-4">
      <SidebarTrigger className="-ml-1" />
      <Separator className="mr-1 h-4" orientation="vertical" />

      <Breadcrumb className="min-w-0">
        <BreadcrumbList>
          <BreadcrumbItem className="hidden sm:block">
            <BreadcrumbLink href="#">Northwind</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator className="hidden sm:block" />
          <BreadcrumbItem>
            <BreadcrumbPage>{TITLES[section]}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="ml-auto flex shrink-0 items-center gap-2">
        <InputGroup className="hidden w-56 sm:flex" size="sm">
          <InputGroupAddon align="inline-start">
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput
            aria-label="Search users"
            onChange={(event) => onSearchChange(event.target.value)}
            placeholder="Search users…"
            type="search"
            value={search}
          />
        </InputGroup>
        <Button aria-label="Notifications" size="icon-sm" variant="ghost">
          <BellIcon />
        </Button>
      </div>
    </header>
  );
}

"use client";

import { type Status, statusLabels, type User } from "@/components/mock-admin";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import {
  SelectionBar,
  SelectionBarButton,
  SelectionBarClose,
  SelectionBarGroup,
  SelectionBarLabel,
  SelectionBarSeparator,
} from "@/components/ui/selection-bar";
import {
  Table,
  TableBody,
  TableCell,
  TableEmpty,
  TableHead,
  TableHeader,
  TableRow,
  TableSortButton,
} from "@/components/ui/table";
import { TablePagination } from "@/components/ui/table-pagination";

export type UserSortKey = "lastActive" | "name" | "role" | "seats";
export type SortDirection = "asc" | "desc";

const columns = [
  { key: "name", label: "User", numeric: false },
  { key: "role", label: "Role", numeric: false },
  { key: "seats", label: "Seats", numeric: true },
  { key: "lastActive", label: "Last active", numeric: false },
] as const;

const STATUS_VARIANT: Record<Status, "default" | "outline" | "secondary"> = {
  active: "secondary",
  invited: "outline",
  suspended: "outline",
};

interface AdminUsersTableProps {
  onClearSelection: () => void;
  onPageIndexChange: (index: number) => void;
  onPageSizeChange: (size: number) => void;
  onSort: (key: UserSortKey) => void;
  onToggleAll: (checked: boolean) => void;
  onToggleRow: (id: string) => void;
  pageCount: number;
  pageIndex: number;
  pageSize: number;
  rows: readonly User[];
  selected: ReadonlySet<string>;
  sort: { direction: SortDirection; key: UserSortKey } | null;
  totalCount: number;
}

export function AdminUsersTable({
  onClearSelection,
  onPageIndexChange,
  onPageSizeChange,
  onSort,
  onToggleAll,
  onToggleRow,
  pageCount,
  pageIndex,
  pageSize,
  rows,
  selected,
  sort,
  totalCount,
}: AdminUsersTableProps) {
  // Binary rather than tri-state: keystone's Checkbox has no indeterminate
  // variant, and re-implementing tickets-01's custom mixed-state button here
  // would duplicate a workaround rather than share one.
  const allOnPageSelected =
    rows.length > 0 && rows.every((row) => selected.has(row.id));

  return (
    <>
      {/* The table goes in CardContent, so the title, the row separators and
          the cell text share the card's horizontal padding. A flush table
          under a padded title leaves the heading indented three times further
          than the columns. */}
      <Card variant="outline">
        <CardHeader>
          <CardTitle className="font-semibold">Users</CardTitle>
        </CardHeader>

        <CardContent className="flex flex-col gap-4">
          <Table hoverable>
            <TableHeader>
              <TableRow>
                <TableHead className="w-10">
                  <Checkbox
                    aria-label="Select all users on this page"
                    checked={allOnPageSelected}
                    onCheckedChange={(checked) => onToggleAll(checked === true)}
                  />
                </TableHead>
                {columns.map((column) => (
                  <TableHead
                    key={column.key}
                    numeric={column.numeric}
                    sortDirection={
                      sort?.key === column.key ? sort.direction : null
                    }
                  >
                    <TableSortButton
                      direction={
                        sort?.key === column.key ? sort.direction : null
                      }
                      onClick={() => onSort(column.key)}
                    >
                      {column.label}
                    </TableSortButton>
                  </TableHead>
                ))}
                {/* Not sortable, so no sortDirection at all — omitting it means
                    no aria-sort, where `null` would claim the column sorts. */}
                <TableHead>Status</TableHead>
              </TableRow>
            </TableHeader>

            <TableBody>
              {rows.length === 0 ? (
                <TableEmpty colSpan={columns.length + 2}>
                  <p className="py-10 text-center text-muted-foreground text-sm">
                    No users match this search.
                  </p>
                </TableEmpty>
              ) : (
                rows.map((row) => (
                  <TableRow
                    data-state={selected.has(row.id) ? "selected" : undefined}
                    key={row.id}
                  >
                    <TableCell>
                      <Checkbox
                        aria-label={`Select ${row.name}`}
                        checked={selected.has(row.id)}
                        onCheckedChange={() => onToggleRow(row.id)}
                      />
                    </TableCell>
                    <TableCell>
                      <div className="font-medium">{row.name}</div>
                      <div className="text-muted-foreground text-xs">
                        {row.email}
                      </div>
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {row.role}
                    </TableCell>
                    <TableCell numeric>{row.seats}</TableCell>
                    <TableCell className="text-muted-foreground">
                      {row.lastActive}
                    </TableCell>
                    <TableCell>
                      <Badge variant={STATUS_VARIANT[row.status]}>
                        {statusLabels[row.status]}
                      </Badge>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>

          <TablePagination
            onPageIndexChange={onPageIndexChange}
            onPageSizeChange={onPageSizeChange}
            pageCount={pageCount}
            pageIndex={pageIndex}
            pageSize={pageSize}
            pageSizeOptions={[5, 10, 20, 50]}
            selectedCount={selected.size}
            totalCount={totalCount}
          />
        </CardContent>
      </Card>

      <SelectionBar open={selected.size > 0}>
        <SelectionBarClose onClick={onClearSelection} />
        <SelectionBarGroup>
          <SelectionBarLabel>
            {selected.size} {selected.size === 1 ? "user" : "users"} selected
          </SelectionBarLabel>
        </SelectionBarGroup>
        <SelectionBarButton>Change role</SelectionBarButton>
        <SelectionBarButton>Resend invite</SelectionBarButton>
        <SelectionBarSeparator />
        <SelectionBarButton tone="destructive">Suspend</SelectionBarButton>
      </SelectionBar>
    </>
  );
}

/**
 * Named value formatters.
 *
 * Panels take `format="money"` rather than a `formatter` function, because the
 * installed entry point of this block is `app/dashboard/page.tsx` — a server
 * component. A function cannot cross that boundary: React rejects it at render
 * time. A block that taught `formatter={(v) => …}` would teach a pattern that
 * breaks the moment someone installs it.
 */

export type ValueFormat = "compact" | "money" | "number" | "percent";

const NUMBER = new Intl.NumberFormat("en-US");
const COMPACT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  notation: "compact",
});
const MONEY = new Intl.NumberFormat("en-US", {
  currency: "USD",
  maximumFractionDigits: 0,
  style: "currency",
});
const PERCENT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  style: "percent",
});

const FORMATTERS: Record<ValueFormat, (value: number) => string> = {
  compact: (value) => COMPACT.format(value),
  money: (value) => MONEY.format(value),
  number: (value) => NUMBER.format(value),
  percent: (value) => PERCENT.format(value),
};

/**
 * `null` stays `null` all the way to the em dash.
 *
 * Coercing with `Number(value)` turns an absent measurement into `0`, which
 * then prints as "$0" or "0%" — a reading the data never took. The distinction
 * between "nothing happened" and "we did not measure" is worth the extra
 * branch.
 */
export function toValue(value: unknown): number | null {
  if (value == null) {
    return null;
  }
  const numeric = typeof value === "number" ? value : Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

export function formatValue(
  value: unknown,
  format: ValueFormat = "number"
): string {
  const numeric = toValue(value);
  return numeric === null ? "—" : FORMATTERS[format](numeric);
}

/**
 * The chart layer for this block, ported from shadcn's `chart.tsx`.
 *
 * Vendored into the block rather than added to `@keystoneui/react` on purpose:
 * it needs recharts, and the library stays dependency-light. A block may carry
 * npm dependencies of its own -- `tickets-01` already does, with `@dnd-kit`.
 *
 * Most of the value is the ~20 `[&_.recharts-*]` overrides on `ChartContainer`,
 * which make recharts' hardcoded `#ccc` and `#fff` marks respect the theme.
 * That list is archaeology, not something to re-derive.
 *
 * Two changes from upstream shadcn, both load-bearing:
 *
 *  - `aspect-auto`, not `aspect-video`. Under an explicit pixel height the
 *    upstream class produces a 462px floor and a horizontal document
 *    scrollbar.
 *  - `min-w-0` added, because a chart is a grid or flex child and those
 *    default to `min-content`.
 *
 * `ChartLegend`/`ChartLegendContent` are dropped: `series-legend.tsx` ships a
 * toggleable legend, so recharts' own `<Legend>` never mounts, and leaving the
 * dead path in would mean two legends to pick between.
 */
"use client";

import * as React from "react";
import type { TooltipValueType } from "recharts";
import * as RechartsPrimitive from "recharts";
import { cn } from "@/lib/utils";

/**
 * Format: { THEME_NAME: CSS_SELECTOR }.
 *
 * Upstream emits a `.dark [data-chart=id]` block as well, so a config can carry
 * a literal colour per mode. Ours never does -- `seriesColor()` returns a
 * `var(--chart-N)` *reference*, and the token already re-steps for dark -- so
 * the second block would be textually identical to the first. One entry.
 */
const THEMES = { light: "" } as const;

const INITIAL_DIMENSION = { width: 320, height: 200 } as const;
type TooltipNameType = number | string;

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>;

type ChartContextProps = {
  config: ChartConfig;
};

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
  initialDimension?: {
    width: number;
    height: number;
  };
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-auto min-w-0 justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-hidden [&_.recharts-surface]:outline-hidden",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color;
    return color ? `  --color-${key}: ${color};` : null;
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  );
};

const ChartTooltip = RechartsPrimitive.Tooltip;

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean;
    hideIndicator?: boolean;
    indicator?: "line" | "dot" | "dashed";
    nameKey?: string;
    labelKey?: string;
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>;
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ]);

  if (!(active && payload?.length)) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      className={cn(
        "grid min-w-32 items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
        className
      )}
    >
      {nestLabel ? null : tooltipLabel}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-medium font-mono text-foreground tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return;
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined;

  let configLabelKey: string = key;

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string;
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string;
  }

  return configLabelKey in config ? config[configLabelKey] : config[key];
}

